{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Viqualine, the closest structural analogue sharing the vinyl-methoxyquinoline and basic amine features, has an absolute oral bioavailability of 80% in healthy subjects after a 25 mg tablet versus intravenous dosing, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Lenvatinib, a methoxyquinoline-containing drug, has an absolute bioavailability of about 85% in humans, indicating that this heteroaromatic system is compatible with high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alizapride, a basic amine with a methoxy-substituted heteroaromatic core, shows a mean systemic availability of 89.7% after oral versus intravenous administration, supporting high oral bioavailability for similarly ionizable, moderately lipophilic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Tegaserod, a methoxyindole basic drug, has a low absolute bioavailability of 11%, providing a low-F counterexample; however, its low structural similarity to the query limits transferability and does not outweigh the closer viqualine evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue viqualine has high absolute oral bioavailability (80%), and other methoxyheteroaromatic basic drugs also show high F; the low-F tegaserod is too structurally distant to override. Therefore the query is predicted to have F >= 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule.",
    "No human pharmacokinetic or first-pass metabolism data for the quinuclidine analogue.",
    "No solubility, permeability, or transporter data specific to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

